let staleTab=false,unlocked=false,lockTimer;
let state=null,storageOK=true,loadError='',cfg={},session=null,dirty=false,revision=null,cloudStatus='기기에 저장',view='home',account='minsu',step=0,chartPeriod='all',chartSource='cycle',chartMetric='assets',filterAccount='all',filterYear='all',showAll=false,lastResult=null,toastTimer,syncTimer,syncing=false,mutating=false,pendingUndo=null;
function readLocal(k,fallback){try{const raw=sessionStorage.getItem(k);return raw?JSON.parse(raw):fallback;}catch(e){if(e instanceof SyntaxError)throw e;storageOK=false;return fallback;}}
try{state=readLocal(KEY,null);cfg=({url:'https://rcauycwrtqtuyllnsxog.supabase.co',key:'sb_publishable_LgwDvvWiaINxb7KYS_lW_A_7E91Q19c'});session=readLocal(SESSIONKEY,null);dirty=readLocal(DIRTYKEY,false);if(state)VR.validateState(state);else if(window.VR_INITIAL){state=VR.validateState(structuredClone(window.VR_INITIAL));}}catch(e){loadError='저장된 기록을 읽지 못했습니다. 백업 파일을 가져와 복구해 주세요. '+e.message;state=null;}
const active=()=>state&&state.accounts.minsu&&state.accounts.bobae;
function writeLocal(k,v){try{sessionStorage.setItem(k,JSON.stringify(v));return true;}catch(e){storageOK=false;return false;}}
function toast(text,error=false){clearTimeout(toastTimer);$('#toast')?.remove();const el=document.createElement('div');el.id='toast';el.className='toast'+(error?' error':'');el.setAttribute('role','status');el.textContent=text;document.body.append(el);toastTimer=setTimeout(()=>el.remove(),6500);}
function persist(){if(!unlocked)throw Error('입장 비밀번호를 입력해 주세요.');if(staleTab)throw Error('다른 탭에서 기록이 바뀌었습니다. 먼저 새로고침해 주세요.');state.updatedAt=new Date().toISOString();const ok=writeLocal(KEY,state);dirty=true;writeLocal(DIRTYKEY,true);cloudStatus=ok?'기기에 저장됨':'임시 보관 · 백업 필요';if(!ok)toast('이 기기에 저장할 수 없습니다. 백업 파일을 내려받아 주세요.',true);if(session&&revision!==null){cloudStatus='동기화 대기';clearTimeout(syncTimer);syncTimer=setTimeout(()=>syncPush(false).catch(e=>toast(e.message,true)),900);}updateStatus();}
function updateStatus(){$$('[data-status]').forEach(el=>el.textContent=cloudStatus);}
function navButton(id,label){return `<button type="button" data-nav="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(id)}<span>${label}</span>${id==='trade'&&view!=='trade'?'<i class="dot"></i>':''}</button>`;}
function render(){
 if(!unlocked){$('#app').innerHTML=gateView();bindNumericPasswords();$('#gate-form').addEventListener('submit',e=>{e.preventDefault();login();});return;}
 const nav=navButton('home','현황')+navButton('trade','거래 진행')+navButton('history','거래 기록')+navButton('prices','종가')+navButton('settings','설정');
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">VR</div><div><b>적립식 VR</b><small>PERSONAL INVESTING</small></div></div><div class="nav-label">MY WORKSPACE</div><nav class="nav" aria-label="주 메뉴">${nav}</nav><div class="side-bottom"><div class="side-note"><strong>2주에 한 번, 화요일</strong>거래를 마치고<br>다음 회차를 준비합니다.<br><span style="color:#b6c6c1">TQQQ · $500 · 14일 RP</span></div><div class="avatar-row"><span class="avatar">M B</span><span>우리의 투자 기록<br><small style="color:#7f9c9f;font-size:9px">민수 &amp; 보배</small></span></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">나의 투자 <span>/</span> ${view==='home'?'대시보드':view==='trade'?'거래 진행':view==='history'?'거래 기록':view==='prices'?'종가 기록':'설정'}</div><div class="mobile-brand"><span class="brand-mark">VR</span>적립식 VR</div><div class="top-actions"><span class="save-status"><i class="status-dot"></i><span data-status>${E(cloudStatus)}</span></span><button class="icon-btn" data-action="backup" aria-label="기록 백업">${icon('download')}</button><button class="icon-btn" data-action="logout" aria-label="잠그기">${icon('lock')}</button></div></header><section id="content">${loadError?`<div class="banner">${E(loadError)}</div>`:''}${!storageOK?'<div class="banner">기기 저장을 사용할 수 없습니다. 사용 후 백업 파일을 내려받아 주세요.</div>':''}${!active()&&view!=='settings'?emptyView():view==='home'?homeView():view==='trade'?tradeView():view==='history'?historyView():view==='prices'?pricesView():settingsView()}</section><footer class="footer"><span>VALUE REBALANCING · TQQQ · USD 기준</span><span>실제 주문은 증권사에서 진행합니다.</span></footer></main><nav class="bottom-nav" aria-label="모바일 주 메뉴">${nav}</nav></div>`;
 bindEvents();if(active()&&view==='home')bindChart();
}
function heading(title,sub,action=''){return `<div class="heading"><div><div class="eyebrow">VALUE REBALANCING</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action}</div>`;}
function emptyView(){return `<div class="empty"><div class="empty-icon">${icon('chart')}</div><div class="eyebrow">YOUR OWN INVESTING SPACE</div><h1>적립식 VR을 한곳에서.</h1><p>민수·보배 계좌의 현황을 확인하고,<br>격주 화요일 거래를 순서대로 기록하세요.</p><div class="buttons"><button class="btn" data-action="import">${icon('upload')}내 기록 가져오기</button><button class="btn" data-action="demo">예시로 둘러보기</button></div><ul class="onboard-list"><li><span>1</span>계좌별 자산과 VR 범위를 확인합니다.</li><li><span>2</span>실제 주식 거래수량과 마지막 RP 금액만 입력합니다.</li><li><span>3</span>변경한 기록을 자동으로 저장합니다.</li></ul><p class="empty-note">이 페이지의 HTML에는 개인 자산 내역이 들어 있지 않습니다.<br>기존 앱에서 내보낸 JSON 백업을 가져오실 수 있습니다.</p></div>`;}
function snapshots(){return ['minsu','bobae'].map(id=>({...VR.currentAccount(state,id),id}));}
function quotePrice(){return prices?.latest?.price||state.quote?.price||snapshots()[0].price;}
function totals(){const q=quotePrice(),ss=snapshots(),assets=ss.reduce((s,a)=>s+a.holdings*q+a.pool,0),principal=ss.reduce((s,a)=>s+a.principal,0),pool=ss.reduce((s,a)=>s+a.pool,0);return {assets,principal,pool,ret:assets/principal-1,profit:assets-principal,q};}
function staleBanner(){if(state.demo)return `<div class="banner">${icon('info')}<span>예시 데이터입니다. 실제 계좌 내역을 반영하지 않습니다.</span><button data-action="import">내 기록 가져오기</button></div>`;const dates=snapshots().map(a=>a.asOf),age=Math.max(...dates.map(d=>(VR.dateMs(VR.today())-VR.dateMs(d))/86400000));if(!state.baselineConfirmed||age>20||!state.quote?.confirmed)return `<div class="banner">${icon('warning')}<span>기록 기준 ${E(dates.sort()[0])} · ${!state.baselineConfirmed?'최신 계좌 잔고 확인이 필요합니다.':'계좌 잔고와 종가 기준일을 확인해 주세요.'}</span><button data-nav="settings">기준 확인</button></div>`;return '';}
function accountCard(s){const assets=s.holdings*quotePrice()+s.pool;return `<article class="card account-card"><div class="card-top"><span class="account-heading"><span class="account-icon ${s.id==='bobae'?'bobae':''}">${s.id==='minsu'?'M':'B'}</span><b style="color:var(--ink);font-weight:600">${names[s.id]}</b></span><span class="tag">TQQQ + RP</span></div><div class="big-value"><small>$</small>${money(assets)}</div><div class="return-line ${assets<s.principal?'negative':''}">${iconTiny()} ${pct(assets/s.principal-1)} <span class="muted">원금 대비</span></div><div class="account-info"><span>TQQQ 보유<b>${money(s.holdings,0)}주</b></span><span>Pool / RP<b>${usd(s.pool)}</b></span></div></article>`;}
function iconTiny(){return '<span aria-hidden="true">↗</span>';}
function homeView(){const t=totals(),ss=snapshots(),next=ss.map(s=>({id:s.id,date:VR.cycleFor(state,s.id)})).sort((a,b)=>a.date.localeCompare(b.date))[0];const d=new Date(VR.dateMs(next.date));return `${heading('적립식 VR 현황','민수와 보배, 두 계좌의 투자 기록입니다.',`<button class="btn" data-action="backup">${icon('download')}기록 백업</button>`)}${staleBanner()}${priceSummary()}<div class="overview"><article class="card total-card"><div class="card-top"><span>두 계좌 총자산</span><span class="tag">USD</span></div><div class="big-value"><small>$</small>${money(t.assets)}</div><div class="return-line">${iconTiny()} ${pct(t.ret)} <span style="color:#94b3b1">누적 수익 ${usd(t.profit)}</span></div><p style="font-size:9px;color:#819fa2;margin:17px 0 0">${E(prices?.latest?.date||state.quote?.actualDate||state.quote?.date||'—')} ${prices?.latest?'미국장 종가':state.quote?.source==='excel_snapshot'?'엑셀 저장가격':'종가'} ${usd(t.q)} 기준</p></article>${ss.map(accountCard).join('')}</div><div class="workspace-grid"><article class="card"><div class="panel-head"><div><h2>자산의 흐름</h2><p>적립한 원금과 자산을 함께 살펴보세요.</p></div><div class="segmented" aria-label="조회 기간">${[['all','전체'],['1y','1년'],['6m','6개월']].map(([id,l])=>`<button data-period="${id}" class="${chartPeriod===id?'active':''}" aria-pressed="${chartPeriod===id}">${l}</button>`).join('')}</div></div><div class="chart-legend"><span><i class="legend-line"></i>${chartMetric==='assets'?'총자산':'원금 대비 수익률'}</span>${chartMetric==='assets'?'<span><i class="legend-line principal"></i>누적 원금</span>':''}<button style="margin-left:auto;font-size:10px;color:var(--teal)" data-action="metric">${chartMetric==='assets'?'수익률 보기':'자산 보기'}</button></div><div class="chart-wrap">${chartSvg()}<div class="chart-hover hide" id="chart-tooltip"></div></div><div class="chart-summary"><div>누적 투자원금<strong>${usd(t.principal,0)}</strong></div><div>누적 수익<strong class="positive">${usd(t.profit,0)}</strong></div><div>현금 비중<strong>${money(t.pool/t.assets*100,1)}%</strong></div></div><div style="display:flex;justify-content:space-between;gap:8px;align-items:center;margin-top:12px"><select class="source-switch" aria-label="그래프 자료 출처" id="chart-source"><option value="cycle" ${chartSource==='cycle'?'selected':''}>계좌별 원본 · 격주</option><option value="weekly" ${chartSource==='weekly'?'selected':''}>VR적립 · 주간 기록</option></select><span style="font-size:9px;color:var(--muted)">수익률은 (자산 ÷ 원금) − 1</span></div><p class="chart-note">주간 기록과 원본 VR의 계산 시점이 달라 출처를 분리했습니다. 거래 내역은 원본 VR을 기준으로 이어집니다.</p></article><article class="card cycle-card"><div class="panel-head"><h2>다음 거래</h2><span class="tag">격주 화요일</span></div><div class="cycle-date"><strong>${d.getUTCMonth()+1}월 ${d.getUTCDate()}일</strong><span>${next.date.slice(0,4)} · 점심시간</span></div><div class="cycle-track"><div class="track-row"><span class="track-n">01</span>외화 RP 매도<small>만기 확인</small></div><div class="track-row"><span class="track-n">02</span>TQQQ 거래<small>월요일 종가</small></div><div class="track-row"><span class="track-n">03</span>$500 환전<small>계좌별</small></div><div class="track-row"><span class="track-n">04</span>14일 RP 매수<small>잔여 달러</small></div></div><button class="btn dark wide" data-nav="trade">거래 확인하기 ${icon('arrow')}</button></article></div><div class="section-line"><h2>최근 거래 기록</h2><button class="btn small ghost" data-nav="history">전체 보기 ${icon('arrow')}</button></div><article class="card history-card">${historyTable(allHistory().slice(0,5))}</article>`;}
let chartData=[];
function series(){const ids=['minsu','bobae'],map=new Map();for(const id of ids){const a=state.accounts[id];let points=(chartSource==='weekly'?a.weekly.map(r=>({...r,date:r.date})):a.history.map(r=>({...r,date:r.asOf})));points=points.filter(r=>r.date<=a.baseline.asOf);points.push({...a.baseline,date:a.baseline.asOf});points.push(...state.records.filter(r=>r.account===id).map(r=>({...r,date:r.asOf})));for(const p of points){if(!map.has(p.date))map.set(p.date,{});map.get(p.date)[id]=p;}}const carry={};let data=[];for(const [date,updates]of [...map].sort((a,b)=>a[0].localeCompare(b[0]))){Object.assign(carry,updates);const assets=ids.reduce((n,id)=>n+(carry[id]?.assets||0),0),principal=ids.reduce((n,id)=>n+(carry[id]?.principal||0),0);if(principal>0)data.push({date,assets,principal,ret:assets/principal-1});}if(chartPeriod!=='all'&&data.length){const cutoff=VR.addDays(data.at(-1).date,chartPeriod==='1y'?-365:-183);data=data.filter(p=>p.date>=cutoff);}return data;}
function chartSvg(){chartData=series();if(!chartData.length)return '<div class="no-data">표시할 자산 기록이 없습니다.</div>';const w=window.innerWidth<620?360:660,h=230,L=47,R=10,T=14,B=25;const values=chartData.flatMap(p=>chartMetric==='assets'?[p.assets,p.principal]:[p.ret]);let min=chartMetric==='assets'?0:Math.min(0,...values),max=Math.max(...values);if(max<=min)max=min+1;max+=Math.abs(max-min)*.12;const X=i=>L+i/(Math.max(1,chartData.length-1))*(w-L-R),Y=v=>h-B-(v-min)/(max-min)*(h-B-T);const points=key=>chartData.map((p,i)=>`${X(i).toFixed(2)},${Y(p[key]).toFixed(2)}`).join(' ');const key=chartMetric==='assets'?'assets':'ret';const main=points(key);let grid='';for(let i=0;i<5;i++){const v=min+(max-min)/4*i,y=Y(v);grid+=`<line x1="${L}" y1="${y}" x2="${w-R}" y2="${y}" stroke="#eaf0f0" stroke-dasharray="3 4"/><text x="${L-9}" y="${y+3}" text-anchor="end">${chartMetric==='assets'?(v>=1000?'$'+money(v/1000,0)+'k':'$'+money(v,0)):money(v*100,0)+'%'}</text>`;}const idxs=[0,Math.floor((chartData.length-1)/3),Math.floor((chartData.length-1)*2/3),chartData.length-1];const ticks=[...new Set(idxs)].map(i=>`<text x="${X(i)}" y="${h-3}" text-anchor="${i===0?'start':i===chartData.length-1?'end':'middle'}">${chartData[i].date.slice(0,7).replace('-','. ')}</text>`).join('');return `<svg class="chart" id="asset-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${chartData[0].date}부터 ${chartData.at(-1).date}까지의 자산과 원금 그래프"><defs><linearGradient id="chart-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#328d78" stop-opacity=".17"/><stop offset="100%" stop-color="#328d78" stop-opacity="0"/></linearGradient></defs>${grid}<polygon points="${L},${h-B} ${main} ${X(chartData.length-1)},${h-B}" fill="url(#chart-fill)"/>${chartMetric==='assets'?`<polyline points="${points('principal')}" fill="none" stroke="#b0bec7" stroke-width="1.4" stroke-dasharray="4 4"/>`:''}<polyline points="${main}" fill="none" stroke="#0a7f6e" stroke-width="2.3" stroke-linejoin="round" stroke-linecap="round"/><circle cx="${X(chartData.length-1)}" cy="${Y(chartData.at(-1)[key])}" r="3.8" fill="#087f71" stroke="white" stroke-width="2"/>${ticks}</svg>`;}
function bindChart(){const el=$('#asset-chart'),tt=$('#chart-tooltip');if(!el||!tt)return;el.addEventListener('pointermove',e=>{const r=el.getBoundingClientRect(),w=el.viewBox.baseVal.width,x=(e.clientX-r.left)/r.width*w,idx=Math.max(0,Math.min(chartData.length-1,Math.round((x-47)/(w-47-10)*(chartData.length-1)))),p=chartData[idx];tt.classList.remove('hide');tt.innerHTML=`${E(p.date)}<br><b>${usd(p.assets)}</b> · ${pct(p.ret)}<br>원금 ${usd(p.principal)}`;tt.style.left=Math.min(Math.max(0,e.clientX-r.left-60),Math.max(0,r.width-170))+'px';tt.style.top='15px';});el.addEventListener('pointerleave',()=>tt.classList.add('hide'));}
function allHistory(){return ['minsu','bobae'].flatMap(id=>[...state.accounts[id].history,...state.records.filter(r=>r.account===id)]).sort((a,b)=>b.cycleDate.localeCompare(a.cycleDate)||a.account.localeCompare(b.account));}
function historyTable(rows,full=false){if(!rows.length)return '<div class="no-data">해당 조건의 기록이 없습니다.</div>';return `<div class="table-scroll"><table><thead><tr><th>거래 회차</th><th>계좌</th><th>주식 거래</th><th>Pool / RP</th><th>총자산</th>${full?'<th>누적 원금</th><th>수익률</th><th>출처</th>':''}</tr></thead><tbody>${rows.map(r=>`<tr><td>${E(r.cycleDate)}</td><td>${names[r.account]}</td><td><span class="trade-badge ${r.quantity>0?'buy':r.quantity<0?'sell':''}">${r.quantity===null?'시작 잔고':r.quantity===0?'유지':money(Math.abs(r.quantity),0)+'주 '+(r.quantity>0?'매수':'매도')}</span></td><td>${usd(r.pool)}</td><td>${usd(r.assets)}</td>${full?`<td>${usd(r.principal)}</td><td class="${r.assets>=r.principal?'positive':'negative'}">${pct(r.assets/r.principal-1)}</td><td style="color:var(--muted)">${r.source==='web'?'앱 기록':r.source==='demo'?'예시':r.source==='baseline'?'기준 잔고':'원본 엑셀'}</td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function historyView(){let rows=allHistory();if(filterAccount!=='all')rows=rows.filter(r=>r.account===filterAccount);if(filterYear!=='all')rows=rows.filter(r=>r.cycleDate.startsWith(filterYear));const years=[...new Set(allHistory().map(r=>r.cycleDate.slice(0,4)))].sort().reverse();return `${heading('거래 기록','회차별 보유수량과 Pool을 확인할 수 있습니다.',`<button class="btn" data-action="csv">${icon('download')}CSV 내보내기</button>`)}<div class="filter-row"><select id="history-account" aria-label="계좌 필터"><option value="all">모든 계좌</option>${Object.entries(names).map(([id,n])=>`<option value="${id}" ${filterAccount===id?'selected':''}>${n}</option>`).join('')}</select><select id="history-year" aria-label="연도 필터"><option value="all">전체 기간</option>${years.map(y=>`<option ${filterYear===y?'selected':''}>${y}</option>`).join('')}</select><span style="margin-left:auto;font-size:10px;color:var(--muted)">USD 기준</span></div><p class="record-total">총 ${rows.length}건 · 원본 엑셀의 거래수량은 직전 회차 잔고와의 차이입니다.</p><article class="card history-card">${historyTable(showAll?rows:rows.slice(0,40),true)}</article>${rows.length>40&&!showAll?'<div style="text-align:center;margin-top:20px"><button class="btn" data-action="show-all">전체 기록 펼치기</button></div>':''}${state.records.length?'<div style="margin-top:22px"><button class="btn small danger" data-action="undo">마지막 앱 거래 취소</button><p class="help">엑셀 원본은 보존합니다. 마지막으로 입력한 앱 거래만 되돌릴 수 있습니다.</p></div>':''}`;}
function draftFor(){const date=VR.cycleFor(state,account),key=account+'-'+date;let draft=state.drafts[key];if(!draft){draft={steps:[false,false,false,false],quantity:null,rp:null,quote:null};}return {date,key,draft};}
function accountPlan(){const a=VR.currentAccount(state,account);return VR.plan({v:VR.nextV(a.v,a.pool,500),holdings:a.holdings,pool:a.pool,price:state.quote.price});}
function saveDraft(draft){const {key}=draftFor();state.drafts[key]=draft;persist();}
function tradeView(){const {date,draft}=draftFor(),gate=VR.canTrade(state,account),prev=VR.currentAccount(state,account);let content='';if(prices?.basis?.hasSplit||prices?.basis?.hasConflict){gate.ok=false;gate.reason=prices.basis.hasSplit?'주식분할이 확인되었습니다. 보유수량과 가격 단위를 확인한 뒤 진행해 주세요.':'종가 출처의 값이 서로 다릅니다. 가격을 확인해 주세요.';}if(lastResult&&lastResult.account===account){const r=lastResult;content=`<div class="success"><div class="success-circle">${icon('check')}</div><h2>${names[account]} 계좌, 기록 완료</h2><p>${r.cycleDate} 회차를 저장했습니다.<br>다음 거래일은 ${r.rpMaturity}입니다.</p><div class="review"><div class="label-value"><span>주식 보유수량</span><b>${money(r.holdings,0)}주</b></div><div class="label-value"><span>최종 RP 매수금액</span><b>${usd(r.pool)}</b></div><div class="label-value"><span>새 누적 원금</span><b>${usd(r.principal)}</b></div></div><button class="btn primary wide" data-action="other-account">${names[account==='minsu'?'bobae':'minsu']} 계좌 확인하기 ${icon('arrow')}</button><button class="btn ghost wide" data-nav="home" style="margin-top:10px">현황으로 돌아가기</button></div>`;}else if(!gate.ok){content=`<div class="trade-lock">${icon('lock')}<h2>거래 기준을 먼저 확인해 주세요.</h2><p>${E(gate.reason)}</p><div class="review"><div class="label-value"><span>이 계좌의 다음 회차</span><b>${date}</b></div><div class="label-value"><span>현재 기준 잔고</span><b>${E(prev.asOf)}</b></div><div class="label-value"><span>필요한 종가 기준일</span><b>${VR.addDays(date,-1)} (월)</b></div></div><button class="btn primary" data-nav="settings">기준 잔고·종가 설정 ${icon('arrow')}</button></div>`;}else{if(draft.quote&&draft.quote!==state.quote.price){draft.steps=[false,false,false,false];draft.quantity=null;draft.rp=null;draft.quote=state.quote.price;state.drafts[draftFor().key]=draft;persist();}content=stepView(date,draft,prev);}
return `${heading('이번 회차 거래',`${lastResult&&lastResult.account===account?lastResult.cycleDate:date} · 계좌별 $500 적립 · 실제 주문은 증권사에서 진행합니다.`)}${staleBanner()}<div class="workflow"><div class="account-tabs">${Object.entries(names).map(([id,n])=>`<button data-account="${id}" class="${account===id?'active':''}"><span class="account-icon ${id==='bobae'?'bobae':''}">${id==='minsu'?'M':'B'}</span><b>${n}</b><small>${state.records.some(r=>r.account===id&&r.cycleDate===VR.today())?'기록 완료':(state.drafts[id+'-'+VR.cycleFor(state,id)]?.steps.filter(Boolean).length||0)+'/4 단계'}</small></button>`).join('')}</div><article class="card">${content}</article></div>`;}
function stepView(date,draft,prev){step=Math.max(0,Math.min(3,step));const p=accountPlan(),labels=['RP 매도','TQQQ 거래','$500 환전','RP 매수'];let body='';if(step===0)body=`<div class="step-eyebrow">STEP 01 / 04</div><h2>먼저 외화 RP를 매도해 주세요.</h2><p class="help">${names[account]} 계좌의 RP 만기를 확인하고 매도합니다. 매도 대금이 달러 현금으로 들어왔는지 확인해 주세요.</p><div class="review"><div class="label-value"><span>직전 Pool / RP</span><b>${usd(prev.pool)}</b></div><div class="label-value"><span>이후 진행</span><b>TQQQ ${p.action}</b></div></div><label class="check"><input type="checkbox" id="step-check" ${draft.steps[0]?'checked':''}>RP 매도 후 달러 현금을 확인했습니다.</label>`;
if(step===1)body=`<div class="step-eyebrow">STEP 02 / 04</div><h2>TQQQ 거래를 진행해 주세요.</h2><div class="order-number ${p.quantity<0?'negative':'positive'}">${p.quantity===0?'거래 없음':money(Math.abs(p.quantity),0)+'<small>주 '+p.action+'</small>'}</div><p class="help">${state.quote.date} 월요일 기준 종가 ${usd(state.quote.price)}로 계산했습니다.${state.quote.actualDate&&state.quote.actualDate!==state.quote.date?'<br>휴장 대체 종가일: '+E(state.quote.actualDate):''}</p><div class="calc-grid"><div>V 목표<b>${usd(p.v,0)}</b></div><div>V 최소 / 최대<b>${money(p.low,0)} / ${money(p.high,0)}</b></div><div>주식 평가금<b>${usd(p.stock,0)}</b></div></div>${p.limited?'<div class="notice">Pool 사용 한도로 매수수량이 제한되었습니다.</div>':''}<div class="field"><label for="trade-qty">입력 1 · 실제 ${p.action==='유지'?'거래':p.action}수량</label><div class="input-suffix"><input id="trade-qty" type="number" inputmode="numeric" min="0" step="1" placeholder="${p.quantity===0?'0을 입력하세요':'실제 체결수량'}" value="${draft.quantity===null?'':Math.abs(draft.quantity)}"><span>주</span></div><small>체결된 수량을 입력해 주세요. 미체결 또는 유지라면 0을 입력합니다. 매수·매도 방향은 계산 결과에 따릅니다.</small></div>`;
if(step===2)body=`<div class="step-eyebrow">STEP 03 / 04</div><h2>원화를 달러로 환전해 주세요.</h2><div class="order-number">$500<small>USD</small></div><p class="help">${names[account]} 계좌에서 원화를 미화 500달러로 환전합니다. 적립금은 회차당 한 번만 반영합니다.</p><div class="notice">주식 주문 후 환전하는 순서입니다. 주식 매수 한도는 환전 전 현금 잔고도 함께 확인해 계산했습니다.</div><label class="check"><input id="step-check" type="checkbox" ${draft.steps[2]?'checked':''}>미화 $500 환전을 완료했습니다.</label>`;
if(step===3)body=`<div class="step-eyebrow">STEP 04 / 04</div><h2>남은 달러로 14일 RP를 매수하세요.</h2><p class="help">주식 거래와 환전을 마친 뒤, 남아 있는 달러 현금을 모두 14일 만기 외화 RP로 매수합니다.</p><div class="field"><label for="rp-amount">입력 2 · 최종 RP 매수금액</label><div class="input-suffix"><input id="rp-amount" type="number" inputmode="decimal" min="0" step="0.01" placeholder="실제 매수한 달러 금액" value="${draft.rp===null?'':draft.rp}"><span>USD</span></div><small>이 금액이 다음 회차의 Pool입니다. RP 이자, 수수료, 실제 체결가 차이가 잔액에 함께 반영됩니다.</small></div><div class="review"><div class="label-value"><span>실제 주식 거래</span><b>${draft.quantity===0?'유지':money(Math.abs(draft.quantity),0)+'주 '+(draft.quantity>0?'매수':'매도')}</b></div><div class="label-value"><span>환전 적립금</span><b>$500.00</b></div><div class="label-value"><span>14일 후 예정일</span><b>${VR.addDays(date,14)}</b></div></div><label class="check"><input id="final-check" type="checkbox">RP 매수 완료 금액을 확인했습니다.</label>`;
return `<div class="stepper" aria-label="거래 단계">${labels.map((l,i)=>`<button data-step="${i}" class="${step===i?'active':draft.steps[i]?'done':''}" ${i>0&&!draft.steps.slice(0,i).every(Boolean)?'disabled':''}><span>${draft.steps[i]?'✓':i+1}</span>${l}</button>`).join('')}</div><div class="step-main">${body}<div class="step-actions">${step>0?'<button class="btn back-btn" data-action="step-back">이전</button>':''}<button class="btn primary" data-action="step-next" ${mutating?'disabled':''}>${step===3?'이번 회차 저장':'완료하고 다음'} ${icon(step===3?'check':'arrow')}</button></div><div class="step-meta">진행상황은 계좌별로 보관됩니다.<br>주문·환전·RP 매수는 증권사에서 직접 진행해 주세요.</div></div>`;}
function settingsView(){const has=active(),a=has?VR.currentAccount(state,'minsu'):null,b=has?VR.currentAccount(state,'bobae'):null,q=state?.quote;return `${heading('설정','계좌의 기준 잔고와 저장 방식을 관리합니다.')}<div class="settings-grid"><article class="card"><h2>기록 가져오기·백업</h2><p class="help">${has?(state.demo?'예시 기록을 보고 있습니다.':'두 계좌의 기록을 보관하고 있습니다.'):'기록을 가져오면 현황과 거래 화면을 사용할 수 있습니다.'}</p><div class="inline-actions"><button class="btn primary" data-action="import">${icon('upload')}JSON 가져오기</button><button class="btn" data-action="backup" ${!has?'disabled':''}>${icon('download')}백업 내려받기</button></div><div class="notice" style="margin-top:18px">GitHub에 올리는 HTML에는 실제 계좌 내역이 포함되지 않습니다. 입장 비밀번호로 보호되는 서버에 기록을 보관하며, 변경사항은 자동 저장됩니다.</div><p class="help">${has?E(state.sourceNote||'VR 앱에서 작성한 기록입니다.'):'동봉된 개인용 HTML에서 백업을 내려받은 후 여기에서 가져오세요.'}</p>${has?'<button class="btn small" data-action="verification">엑셀 계산 검증 보기</button>':''}</article><article class="card"><h2>거래 기준 종가</h2><p class="help">두 계좌에 같은 종가를 사용합니다. 기준일은 거래 전 월요일이며, 미국 휴장이면 그 이전 최근 거래일의 종가를 입력합니다.</p><form id="quote-form"><div class="form-grid"><div class="field"><label for="quote-date">기준 월요일</label><input id="quote-date" type="date" required value="${E(q?.date||'')}" ${!has?'disabled':''}></div><div class="field"><label for="actual-date">실제 종가일 (미국)</label><input id="actual-date" type="date" required value="${E(q?.actualDate||q?.date||'')}" ${!has?'disabled':''}></div></div><div class="field"><label for="quote-price">TQQQ 종가 (USD)</label><input id="quote-price" type="number" min="0.0001" step="0.0001" inputmode="decimal" required value="${q?.price||''}" ${!has?'disabled':''}></div><label class="check checkbox-inline"><input id="quote-confirm" type="checkbox" required ${q?.confirmed?'checked':''} ${!has?'disabled':''}>해당 미국 거래일의 종가와 주식분할 여부를 확인했습니다.</label><div class="inline-actions"><button class="btn primary" type="submit" ${!has?'disabled':''}>종가 저장</button><button class="btn" type="button" data-action="fetch-quote" ${!has||!session?'disabled':''}>종가 자동 조회</button></div><small class="help">입장 후 종가를 조회할 수 있습니다. 조회 결과를 확인한 다음 저장해 주세요.</small></form></article></div><div class="section-line"><h2>계좌 기준 잔고</h2><small>처음 시작하거나 누락 회차를 정리할 때</small></div><article class="card">${has?`<p class="help" style="margin-top:0">마지막 완료 회차의 잔고를 입력합니다. 다음 V값은 아래 V와 Pool로 계산하며 $500 적립을 한 번 더합니다. 과거 원본 기록은 보존됩니다.</p><form id="baseline-form"><div class="form-grid"><div class="field"><label for="next-date">다음 거래일 (화요일)</label><input id="next-date" type="date" required value="${VR.cycleFor(state,'minsu')}"><small>두 계좌가 같은 회차부터 시작합니다.</small></div><div class="field"><label for="baseline-asof">잔고 확인일</label><input id="baseline-asof" type="date" required value="${E(a.asOf)}"><small>다음 거래일 전일까지의 확정 잔고입니다.</small></div></div><div class="two-col">${[['minsu',a],['bobae',b]].map(([id,s])=>`<div><h3 style="margin-top:12px">${names[id]} 계좌</h3><div class="form-grid"><div class="field"><label for="${id}-holdings">TQQQ 보유수량</label><input id="${id}-holdings" type="number" min="0" step="1" required value="${s.holdings}"></div><div class="field"><label for="${id}-pool">Pool / RP 잔액 (USD)</label><input id="${id}-pool" type="number" min="0" step="0.001" required value="${s.pool}"></div><div class="field"><label for="${id}-v">직전 회차 V값</label><input id="${id}-v" type="number" min="0.000001" step="any" required value="${s.v}"></div><div class="field"><label for="${id}-principal">누적 투자원금 (USD)</label><input id="${id}-principal" type="number" min="0.01" step="0.01" required value="${s.principal}"></div></div></div>`).join('')}</div><label class="check"><input type="checkbox" id="baseline-confirm" required ${state.baselineConfirmed?'checked':''}>최신 계좌 잔고를 확인했습니다. 기준 잔고를 바꾸면 앱 거래 내역은 보관 기록으로 이동하고 새 기준부터 시작합니다.</label><button class="btn primary" type="submit">기준 잔고 저장</button></form>`:'<p class="help">먼저 기록을 가져오거나 예시 데이터를 열어 주세요.</p>'}</article><div class="section-line"><h2>저장과 입장 비밀번호</h2><small>나만의 투자 기록</small></div><div class="settings-grid"><article class="card"><h2>자동 저장</h2><p class="help"><b>${E(cloudStatus)}</b><br>변경한 기록은 서버에 자동 저장됩니다. 다른 기기에서도 같은 입장 비밀번호로 이어서 사용할 수 있습니다.</p><div class="inline-actions"><button class="btn" data-action="cloud-pull">서버 기록 불러오기</button><button class="btn" data-action="cloud-push">이 기기 기록 올리기</button><button class="btn" data-action="logout">잠그기</button></div><p class="help">입장은 이 탭에서 최대 8시간 유지됩니다. 수정이 겹치면 자동 저장을 멈추고 알려드립니다.</p></article><article class="card"><h2>입장 비밀번호 변경</h2><p class="help">여기서 바꾸는 비밀번호는 VR에만 적용됩니다.</p><form id="password-form"><div class="field"><label for="current-password">현재 비밀번호</label><input id="current-password" type="password" class="numeric-password" data-numeric-password inputmode="numeric" pattern="[0-9]*" autocomplete="off" autocapitalize="none" autocorrect="off" spellcheck="false" required maxlength="72"></div><div class="field"><label for="new-password">새 비밀번호</label><input id="new-password" type="password" class="numeric-password" data-numeric-password inputmode="numeric" pattern="[0-9]*" autocomplete="off" autocapitalize="none" autocorrect="off" spellcheck="false" required minlength="8" maxlength="72"><small>8자리 이상의 숫자로 입력해 주세요.</small></div><div class="field"><label for="new-password-confirm">새 비밀번호 확인</label><input id="new-password-confirm" type="password" class="numeric-password" data-numeric-password inputmode="numeric" pattern="[0-9]*" autocomplete="off" autocapitalize="none" autocorrect="off" spellcheck="false" required minlength="8" maxlength="72"></div><button class="btn primary" type="submit">비밀번호 변경</button></form></article></div><div class="settings-section"><details><summary class="detail-summary">계산 방식과 데이터 기준</summary><div class="card"><div class="label-value"><span>V 갱신식</span><b>직전 V × ROUND(1 + Pool ÷ V ÷ 10, 3) + 500</b></div><div class="label-value"><span>밴드 / Pool 사용 한도</span><b>±20% / 75%</b></div><p class="help">밴드 하단 미만이면 최소 밴드까지 올리는 정수 수량을 매수하고, 상단 초과이면 상단보다 아래로 내리는 정수 수량을 매도합니다. 주식 주문 전에는 환전 예정 $500를 사용할 수 없으므로 실제 보유 현금도 매수 한도에 반영합니다. 밴드에 정확히 닿으면 유지합니다. 원본 시트와 같이 추가 필요 매수액이 1주 가격 이하인 경우에도 유지합니다.</p><p class="help">수익률은 달러 총자산 ÷ 누적 달러원금 − 1인 단순 누적 수익률입니다. 연환산 수익률·시간가중 수익률이 아닙니다. RP 만기는 달력 기준 14일 예정일이며 실제 만기와 휴일 처리는 증권사에서 확인합니다.</p><p class="help">두 입력만으로 실제 체결단가·수수료·RP 이자를 각각 산출할 수는 없습니다. 실제 보유수량과 최종 RP 잔액은 확정값으로 저장하고 평가에는 기준 종가를 사용합니다.</p></div></details></div>`;}
function bindNumericPasswords(){
 $$('.numeric-password').forEach(input=>{
  // Samsung keyboards use the numeric layout reliably with masked text inputs.
  if(window.CSS?.supports?.('-webkit-text-security','disc'))input.type='text';
  input.addEventListener('input',()=>{input.value=input.value.replace(/\D/g,'');});
 });
}
function bindEvents(){
 bindNumericPasswords();
 $$('[data-price-symbol]').forEach(b=>b.addEventListener('click',()=>{priceSymbol=b.dataset.priceSymbol;render();}));
 $$('[data-nav]').forEach(b=>b.addEventListener('click',()=>{view=b.dataset.nav;lastResult=null;render();window.scrollTo({top:0,behavior:'instant'});}));
 $$('[data-action]').forEach(b=>b.addEventListener('click',()=>runAction(b.dataset.action)));
 $$('[data-period]').forEach(b=>b.addEventListener('click',()=>{chartPeriod=b.dataset.period;render();}));
 $$('[data-account]').forEach(b=>b.addEventListener('click',()=>{account=b.dataset.account;step=0;lastResult=null;render();}));
 $$('[data-step]').forEach(b=>b.addEventListener('click',()=>{captureInputs();step=+b.dataset.step;render();}));
 $('#trade-qty')?.addEventListener('input',()=>captureInputs());$('#rp-amount')?.addEventListener('input',()=>captureInputs());
 $('#step-check')?.addEventListener('change',()=>captureInputs());
 $('#chart-source')?.addEventListener('change',e=>{chartSource=e.target.value;render();});
 $('#history-account')?.addEventListener('change',e=>{filterAccount=e.target.value;showAll=false;render();});
 $('#history-year')?.addEventListener('change',e=>{filterYear=e.target.value;showAll=false;render();});
 $('#quote-form')?.addEventListener('submit',e=>{e.preventDefault();saveQuote();});
 $('#baseline-form')?.addEventListener('submit',e=>{e.preventDefault();saveBaseline();});
 $('#password-form')?.addEventListener('submit',async e=>{e.preventDefault();await changePassword();});
}
function captureInputs(){if(!active()||view!=='trade')return;const {draft}=draftFor();let changed=false;if(step===1&&$('#trade-qty')){const raw=$('#trade-qty').value,p=accountPlan();const n=raw===''?null:Number(raw);draft.quantity=n===null?null:n*(p.quantity<0?-1:1);draft.steps[1]=false;draft.steps[2]=false;draft.steps[3]=false;draft.quote=state.quote.price;changed=true;}if(step===3&&$('#rp-amount')){draft.rp=$('#rp-amount').value===''?null:Number($('#rp-amount').value);changed=true;}if((step===0||step===2)&&$('#step-check')){draft.steps[step]=$('#step-check').checked;if(!draft.steps[step])for(let i=step+1;i<4;i++)draft.steps[i]=false;changed=true;}if(changed)saveDraft(draft);}
function saveQuote(){try{const date=$('#quote-date').value,actualDate=$('#actual-date').value,price=Number($('#quote-price').value);if(new Date(VR.dateMs(date)).getUTCDay()!==1)throw Error('기준일은 월요일로 선택해 주세요.');if(VR.dateMs(actualDate)>VR.dateMs(date)||VR.dateMs(actualDate)<VR.dateMs(VR.addDays(date,-7)))throw Error('실제 종가일은 기준 월요일 또는 그 이전 7일 이내여야 합니다.');if([0,6].includes(new Date(VR.dateMs(actualDate)).getUTCDay()))throw Error('실제 종가일은 미국 거래일로 입력해 주세요.');if(!Number.isFinite(price)||price<=0)throw Error('종가를 확인해 주세요.');const due=VR.addDays(date,1);if(due>VR.today())throw Error('아직 완료되지 않은 월요일 종가를 저장할 수 없습니다.');if(Object.values(state.drafts).some(d=>d.steps.some(Boolean))){confirmDialog('종가를 변경하시겠습니까?','진행 중인 거래 단계가 초기화됩니다. 실제 주문 내역과 새 종가를 확인해 주세요.','변경',()=>applyQuote({price,date,actualDate,source:'manual',confirmed:true}));return;}applyQuote({price,date,actualDate,source:'manual',confirmed:true});}catch(e){toast(e.message,true);}}
function applyQuote(q){state.quote=q;state.drafts={};persist();render();toast('두 계좌에 적용할 종가를 저장했습니다.');}
function saveBaseline(){try{const next=$('#next-date').value,asOf=$('#baseline-asof').value;if(new Date(VR.dateMs(next)).getUTCDay()!==2)throw Error('다음 거래일은 화요일로 지정해 주세요.');if(asOf>=next||asOf>VR.today())throw Error('잔고 확인일은 오늘 이하이며 다음 거래일 전이어야 합니다.');const baselines={};for(const id of Object.keys(names)){const b={account:id,id:id+'-baseline-'+next,cycleDate:VR.addDays(next,-14),asOf,holdings:Number($('#'+id+'-holdings').value),pool:Number($('#'+id+'-pool').value),v:Number($('#'+id+'-v').value),principal:Number($('#'+id+'-principal').value),price:quotePrice(),quantity:null,contribution:0,source:'baseline'};b.assets=b.holdings*b.price+b.pool;VR.validateBaseline(b);baselines[id]=b;}const apply=()=>{for(const id of Object.keys(names)){const a=state.accounts[id];a.history.push(...state.records.filter(r=>r.account===id));a.history=a.history.filter((r,i,arr)=>arr.findIndex(x=>x.id===r.id)===i);a.baseline=baselines[id];}state.records=[];state.drafts={};state.baselineConfirmed=true;state.demo=false;persist();render();toast('기준 잔고를 저장했습니다. 거래일과 종가를 확인해 주세요.');};confirmDialog('새 기준 잔고를 저장할까요?','원본 엑셀 기록은 보존하고, 앱 거래는 조회용 기록으로 옮깁니다. 다음 회차부터 입력한 잔고로 계산합니다.','저장',apply);}catch(e){toast(e.message,true);}}
function runAction(action){try{switch(action){case'prices-refresh':refreshDailyPrices();break;case'prices-all':allPrices=true;render();break;case'prices-csv':exportDailyCSV();break;case'backup':backup();break;case'import':$('#import-file').value='';$('#import-file').click();break;case'demo':confirmDialog('예시로 둘러보기','가상 금액으로 화면과 기록 방식을 살펴봅니다. 기존 기록이 있으면 먼저 백업해 주세요.','예시 열기',()=>{state=makeDemo();persist();loadError='';view='home';render();});break;case'metric':chartMetric=chartMetric==='assets'?'return':'assets';render();break;case'show-all':showAll=true;render();break;case'csv':exportCSV();break;case'step-back':captureInputs();step=Math.max(0,step-1);render();break;case'step-next':nextStep();break;case'other-account':account=account==='minsu'?'bobae':'minsu';step=0;lastResult=null;render();break;case'verification':verification();break;case'cloud-pull':cloudPullPrompt();break;case'cloud-push':cloudPushPrompt();break;case'fetch-quote':fetchQuote();break;case'logout':logout();break;case'undo':undo();break;}}catch(e){toast(e.message,true);}}
function nextStep(){if(staleTab){toast('다른 탭에서 기록이 바뀌었습니다. 먼저 새로고침해 주세요.',true);return;}if(mutating)return;try{captureInputs();const {draft,key:draftKey}=draftFor();if((step===0||step===2)&&!draft.steps[step])throw Error('완료 여부를 확인해 주세요.');if(step===1){if(!Number.isInteger(draft.quantity)||$('#trade-qty').value===''||Number($('#trade-qty').value)<0)throw Error('실제 체결수량을 0 이상의 정수로 입력해 주세요.');const p=accountPlan(),prev=VR.currentAccount(state,account);if(Math.abs(draft.quantity)>Math.abs(p.quantity))throw Error('실제 수량이 계산 수량보다 큽니다. 거래 내역과 기준 잔고를 확인해 주세요.');if(prev.holdings+draft.quantity<0)throw Error('보유수량을 초과해 매도할 수 없습니다.');draft.steps[1]=true;saveDraft(draft);}if(step<3){step++;render();return;}if(!$('#final-check').checked)throw Error('RP 매수 완료 금액을 확인해 주세요.');mutating=true;const record=VR.complete(state,account,draft);state.records.push(record);delete state.drafts[draftKey];lastResult=record;persist();mutating=false;render();toast('이번 회차를 저장했습니다.');}catch(e){mutating=false;toast(e.message,true);}}
function download(name,text,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function backup(){if(!active()){toast('아직 백업할 기록이 없습니다.');return;}download('VR_backup_'+VR.today()+'.json',JSON.stringify(state,null,2));}
function exportCSV(){if(!active())return;const rows=allHistory().filter(r=>(filterAccount==='all'||r.account===filterAccount)&&(filterYear==='all'||r.cycleDate.startsWith(filterYear)));const header=['거래회차','기준일','계좌','주식거래수량(매수+,매도-)','보유수량','Pool_USD','기준가격_USD','V','누적원금_USD','총자산_USD','단순누적수익률','출처'];const escape=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const data=rows.map(r=>[r.cycleDate,r.asOf,names[r.account],r.quantity,r.holdings,r.pool,r.price,r.v,r.principal,r.assets,r.assets/r.principal-1,r.source]);download('VR_history_'+VR.today()+'.csv','\ufeff'+[header,...data].map(r=>r.map(escape).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
function confirmDialog(title,text,label,fn){const d=$('#confirm-dialog');d.innerHTML=`<h2>${E(title)}</h2><p>${E(text)}</p><div class="inline-actions"><button class="btn primary" id="dialog-yes">${E(label)}</button><button class="btn" id="dialog-no">취소</button></div>`;d.showModal();$('#dialog-no').onclick=()=>d.close();$('#dialog-yes').onclick=()=>{d.close();Promise.resolve().then(fn).catch(e=>toast(e.message,true));};}
function verification(){const v=window.VR_VERIFICATION;const d=$('#confirm-dialog');d.innerHTML=`<h2>엑셀 계산 검증</h2><p>계좌별 원본 시트의 저장된 계산 결과와 앱의 계산식을 대조했습니다.</p>${v?`<ul class="health-list"><li>V 갱신: <b>${v.targetChecks}개 일치</b></li><li>밴드 계산: <b>${v.bandChecks}개 일치</b></li><li>잔고 수량 × 가격: <b>${v.valuationChecks}개 일치</b></li><li>원본의 추가 필요 거래액: <b>${v.remainingChecks}개 일치</b></li><li>완료 회차 Pool 연속성: <b>${v.poolChecks}개 일치</b></li></ul>`:'<p>배포 패키지의 tests 폴더에서 검증 결과를 확인할 수 있습니다.</p>'}<p>검증은 첨부 엑셀의 저장된 결과를 기준으로 합니다. 실제 최신 잔고 및 외부 종가 조회 검증과는 별개입니다. 새 거래에서는 환전 전 가용 현금도 매수 한도에 반영합니다.</p><button class="btn primary" id="verify-close">확인</button>`;d.showModal();$('#verify-close').onclick=()=>d.close();}
function undo(){const candidates=state.records.slice().sort((a,b)=>(b.createdAt||'').localeCompare(a.createdAt||''));if(!candidates.length)return;const r=candidates[0];confirmDialog('마지막 앱 거래를 취소할까요?',`${names[r.account]} 계좌 ${r.cycleDate} 회차의 ${r.quantity}주 거래와 RP ${usd(r.pool)} 기록을 취소합니다. 증권사 주문은 취소되지 않습니다.`,'기록 취소',()=>{state.records=state.records.filter(x=>x.id!==r.id);state.drafts={};persist();lastResult=null;render();toast('앱 거래 기록을 취소했습니다.');});}
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>12*1024*1024)throw Error('12MB 이하의 JSON 파일을 선택해 주세요.');const incoming=VR.validateState(JSON.parse(await file.text()));const apply=()=>{if(active())download('VR_before_import_'+VR.today()+'.json',JSON.stringify(state,null,2));state=incoming;loadError='';state.drafts={};revision=null;persist();view='home';lastResult=null;step=0;render();toast('두 계좌의 기록을 가져왔습니다.');};confirmDialog('기록을 가져올까요?','가져온 파일로 이 기기의 기록을 바꿉니다. 기존 기록이 있으면 변경 전 백업을 내려받습니다.','가져오기',apply);}catch(err){toast('가져오기 실패: '+err.message,true);}});
function makeDemo(){const s=VR.blank(),next=nextTuesday(VR.today()),prevDate=VR.addDays(next,-14),asOf=VR.addDays(next,-1);for(const [id,scale]of [['minsu',1],['bobae',1.5]]){const hist=[];for(let i=0;i<30;i++){const date=VR.addDays(prevDate,-14*(29-i)),principal=(15000+i*500)*scale,assets=principal*(.84+i*.018+Math.sin(i*.65)*.11),pool=assets*.2;hist.push({id:id+'-demo-'+i,account:id,cycleDate:date,asOf:VR.addDays(date,13),v:assets*.82,holdings:Math.floor((assets-pool)/50),pool:VR.round(pool),price:50,principal,assets,quantity:0,contribution:500,source:'demo'});}for(const h of hist)h.assets=h.holdings*h.price+h.pool;const baseline=hist.at(-1);s.accounts[id]={id,name:names[id],baseline,history:hist,weekly:[]};}s.quote={price:50,date:VR.addDays(next,-1),source:'demo',confirmed:false};s.baselineConfirmed=false;s.demo=true;s.sourceNote='이 기록은 화면 확인용 가상 데이터입니다.';return s;}
function nextTuesday(day){const w=new Date(VR.dateMs(day)).getUTCDay();return VR.addDays(day,(2-w+7)%7);}
function gateView(){return `<main class="gate-shell"><section class="gate-card"><div class="brand-mark">VR</div><div class="eyebrow">OUR INVESTING RECORD</div><h1>적립식 VR</h1><p>민수와 보배의 투자 기록입니다.<br>입장 비밀번호를 입력해 주세요.</p><form id="gate-form"><div class="field"><label for="gate-password">입장 비밀번호</label><input id="gate-password" type="password" class="numeric-password" data-numeric-password inputmode="numeric" pattern="[0-9]*" autocomplete="off" autocapitalize="none" autocorrect="off" spellcheck="false" required maxlength="72" autofocus placeholder="비밀번호"></div><button class="btn primary wide" type="submit">입장하기 ${icon('arrow')}</button><p id="gate-error" class="gate-error" role="status"></p></form><p class="gate-help">처음에는 기존 자산관리 페이지의 편집용 비밀번호로 입장할 수 있습니다.</p></section></main>`;}
const errors={invalid_password:'비밀번호가 맞지 않습니다.',temporarily_locked:'입력 오류가 반복되어 잠겼습니다. 5분 뒤 다시 시도해 주세요.',session_expired:'입장 시간이 만료되었습니다. 비밀번호를 다시 입력해 주세요.',invalid_new_password:'새 비밀번호는 8자 이상, 72바이트 이하로 입력해 주세요.',revision_conflict:'revision_conflict',invalid_state:'저장할 기록의 형식이 올바르지 않습니다.'};
function keepSession(value){session=value;writeLocal(SESSIONKEY,value);clearTimeout(lockTimer);if(value){lockTimer=setTimeout(()=>lockGate(),Math.max(0,Date.parse(value.expiresAt)-Date.now()));}}
function lockGate(){clearTimeout(syncTimer);clearTimeout(lockTimer);unlocked=false;prices=null;session=null;revision=null;writeLocal(SESSIONKEY,null);cloudStatus='잠김';$('#confirm-dialog')?.close();render();}
async function gateway(action,data={}){if(action!=='login')await ensureSession();const res=await fetch(cfg.url+'/rest/v1/rpc/vr_gateway',{method:'POST',headers:{apikey:cfg.key,'Content-Type':'application/json'},body:JSON.stringify({p_action:action,p_token:action==='login'?null:session.token,p_data:data}),signal:AbortSignal.timeout(18000)});const r=await res.json();if(!res.ok)throw Error(r?.message||'연결 실패 ('+res.status+')');if(r?.error){if(r.error==='session_expired')lockGate();throw Error(errors[r.error]||r.error);}return r;}
async function api(path,{method='GET',body}={}){await ensureSession();const res=await fetch(cfg.url+path,{method,headers:{apikey:cfg.key,'Content-Type':'application/json',Authorization:'Bearer '+session.token},body:body===undefined?undefined:JSON.stringify(body),signal:AbortSignal.timeout(18000)});const data=await res.json();if(res.status===401)lockGate();if(!res.ok)throw Error(data?.message||'연결 실패 ('+res.status+')');return data;}
async function ensureSession(){if(!session?.token||Date.parse(session.expiresAt)<=Date.now()){lockGate();throw Error('입장 비밀번호를 입력해 주세요.');}}
async function login(){const input=$('#gate-password'),btn=$('#gate-form button');btn.disabled=true;$('#gate-error').textContent='기록을 여는 중입니다.';try{const r=await gateway('login',{password:input.value});input.value='';keepSession(r);await resumeCloud(true);}catch(e){if(!unlocked){$('#gate-error').textContent=e.message;$('#gate-password').value='';}else toast(e.message,true);}finally{if(btn.isConnected)btn.disabled=false;}}
async function resumeCloud(fresh=false){if(!session)return;try{const r=await remote();
 // A legacy unsaved real record is preserved for an explicit choice after unlocking.
 if(fresh&&!state){try{const legacy=JSON.parse(localStorage.getItem(KEY)||'null'),changed=JSON.parse(localStorage.getItem(DIRTYKEY)||'false');if(legacy&&changed&&!legacy.demo&&!(legacy.sourceNote||'').includes('가상 데이터')){VR.validateState(legacy);state=legacy;dirty=true;}}catch{}}
 if(r&&(!active()||state.demo||!dirty)){VR.validateState(r.state);state=r.state;revision=r.revision;dirty=false;writeLocal(KEY,state);writeLocal(DIRTYKEY,false);cloudStatus='자동 저장 연결됨';loadError='';}
 else if(!r){revision=0;cloudStatus='입장 완료 · 기록 가져오기 필요';}else{revision=null;cloudStatus='기기 변경 있음 · 저장 방식 선택';}
 unlocked=true;keepSession(session);render();loadDailyPrices();
 }catch(e){unlocked=false;keepSession(null);render();$('#gate-error').textContent=e.message;throw e;}}
async function logout(){if(syncing){toast('저장을 마친 후 잠가 주세요.',true);return;}if(dirty&&active()&&!state.demo){confirmDialog('저장하지 못한 변경이 있습니다.','백업 파일을 먼저 내려받은 뒤 잠급니다. 다음 입장 시 저장 방식을 선택할 수 있습니다.','백업하고 잠그기',async()=>{backup();await finishLogout();});return;}await finishLogout();}
async function finishLogout(){try{if(session)await gateway('logout');}catch{}lockGate();}
async function changePassword(){const form=$('#password-form');if(!form.reportValidity())return;const current=$('#current-password').value,next=$('#new-password').value;if(next!==$('#new-password-confirm').value){toast('새 비밀번호가 서로 다릅니다.',true);return;}const button=form.querySelector('button');button.disabled=true;try{const r=await gateway('password',{password:current,newPassword:next});keepSession(r);render();toast('VR 입장 비밀번호를 변경했습니다. 다른 기기는 다시 입장해야 합니다.');}catch(e){toast(e.message,true);}finally{if(button.isConnected)button.disabled=false;['#current-password','#new-password','#new-password-confirm'].forEach(id=>{if($(id))$(id).value='';});}}
async function remote(){return gateway('load');}
function cloudPullPrompt(){confirmDialog('클라우드 기록을 불러올까요?','이 기기 기록을 클라우드 기록으로 바꿉니다. 기존 기기 기록은 먼저 백업 파일로 내려받습니다.','불러오기',async()=>{if(syncing)throw Error('진행 중인 동기화가 끝난 뒤 시도해 주세요.');const r=await remote();if(!r)throw Error('클라우드에 아직 기록이 없습니다. 이 기기 기록을 먼저 올려 주세요.');VR.validateState(r.state);if(active())backup();state=r.state;revision=r.revision;dirty=false;writeLocal(KEY,state);writeLocal(DIRTYKEY,false);cloudStatus='클라우드 동기화됨';loadError='';render();toast('클라우드 기록을 불러왔습니다.');});}
function cloudPushPrompt(){if(!active())throw Error('먼저 이 기기에 기록을 가져와 주세요.');confirmDialog('이 기기 기록을 클라우드에 올릴까요?','클라우드에 다른 기록이 있으면 이 기기 기록으로 교체합니다. 이후 변경 내용은 자동으로 동기화됩니다.','올리기',async()=>{if(syncing)throw Error('진행 중인 동기화가 끝난 뒤 시도해 주세요.');const r=await remote();revision=r?.revision||0;await syncPush(true);render();});}
async function syncPush(force){if(syncing)return;if(!unlocked||!active()||state.demo||!session||revision===null)return;if(!dirty&&!force)return;syncing=true;const sentAt=state.updatedAt,expected=revision,snapshot=structuredClone(state);cloudStatus='클라우드 저장 중';updateStatus();try{VR.validateState(snapshot);const result=await gateway('save',{state:snapshot,revision:expected});revision=result.revision;if(state.updatedAt===sentAt){dirty=false;writeLocal(DIRTYKEY,false);cloudStatus='클라우드 동기화됨';}else{cloudStatus='변경사항 동기화 대기';clearTimeout(syncTimer);syncTimer=setTimeout(()=>syncPush(false).catch(e=>toast(e.message,true)),1200);}if(force)toast('클라우드에 기록을 저장했습니다.');}catch(e){if(/revision_conflict/.test(e.message)){revision=null;cloudStatus='수정 충돌 · 동기화 중지';throw Error('다른 기기의 기록이 변경되었습니다. 기기 백업 후 클라우드 기록을 확인해 주세요.');}cloudStatus='기기 저장됨 · 동기화 실패';throw Error('동기화 실패: '+e.message);}finally{syncing=false;updateStatus();}}
async function fetchQuote(){try{if(Object.values(state.drafts).some(d=>d.steps.some(Boolean)))throw Error('거래 진행 중에는 종가를 바꿀 수 없습니다.');const date=$('#quote-date').value;let d=await readDailyPrices(date,priceSince());if(!d.basis){await api('/functions/v1/vr-daily-prices',{method:'POST',body:{}});d=await readDailyPrices(date,priceSince());}const q=d.basis;if(!q)throw Error('저장된 종가가 없습니다. 잠시 뒤 다시 시도하거나 수동 입력해 주세요.');if(q.hasSplit||q.hasConflict)throw Error('주식분할 또는 종가 차이가 확인되었습니다. 가격과 수량 단위를 확인해 주세요.');$('#quote-price').value=q.price;$('#actual-date').value=q.actualDate;$('#quote-confirm').checked=false;toast('저장된 미국장 종가를 불러왔습니다. 확인 후 저장해 주세요.');}catch(e){toast(e.message,true);}}
window.addEventListener('online',()=>{if(dirty&&revision!==null)syncPush(false).catch(e=>toast(e.message,true));});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){staleTab=true;clearTimeout(syncTimer);revision=null;cloudStatus='다른 탭 변경 · 새로고침 필요';updateStatus();toast('다른 탭에서 기록이 변경되었습니다. 이 탭을 새로고침해 주세요.',true);$$('[data-action="step-next"]').forEach(b=>b.disabled=true);}});
render();
if(session)resumeCloud().catch(()=>{});
document.addEventListener('visibilitychange',()=>{if(session&&Date.parse(session.expiresAt)<=Date.now())lockGate();});
